const APPROVED_POLICY_VALUES = new Set(['allowed', 'allowed-with-notice']);
const PROHIBITED_CONTROL_PLANE_FIELDS = new Set([
  'project',
  'projectData',
  'projectId',
  'revision',
  'revisionId',
  'history',
  'portableBackup',
]);
const DESCRIPTOR_FIELDS = new Set(['assetId', 'version', 'resource', 'provenance', 'assetUsageGrant']);
const RESOURCE_FIELDS = new Set(['sha256', 'mediaType', 'byteLength']);
const PROVENANCE_FIELDS = new Set(['evidenceId', 'sourceKind']);
const GRANT_FIELDS = new Set([
  'backupPackagingPolicy',
  'evidenceKind',
  'inAppRenderAndThumbnailPolicy',
  'modelAndSubresourcePolicy',
  'noticePlacementPolicy',
  'optimizationAndTranscodingPolicy',
  'private3dTransferPolicy',
  'renderedPngDownloadAndSharePolicy',
  'requiredNotices',
]);
const NOTICE_FIELDS = new Set(['text', 'placements']);
const REQUIRED_GRANT_POLICIES = [
  'inAppRenderAndThumbnailPolicy',
  'modelAndSubresourcePolicy',
  'optimizationAndTranscodingPolicy',
  'backupPackagingPolicy',
  'private3dTransferPolicy',
  'renderedPngDownloadAndSharePolicy',
  'noticePlacementPolicy',
];

const addIfMissing = (reasonCodes, condition, code) => {
  if (condition && !reasonCodes.includes(code)) {
    reasonCodes.push(code);
  }
};

const isPlainObject = (value) => Object.prototype.toString.call(value) === '[object Object]';

const isNonEmptyString = (value) => typeof value === 'string' && value.trim().length > 0;

const isValidSha256 = (value) => typeof value === 'string' && /^[a-f0-9]{64}$/i.test(value);

const isValidByteLength = (value) => Number.isSafeInteger(value) && value > 0;

const hasProhibitedField = (value, inspected = new WeakSet()) => {
  if (value === null || typeof value !== 'object') {
    return false;
  }
  if (inspected.has(value)) {
    return false;
  }
  inspected.add(value);

  return Object.entries(value).some(([field, nestedValue]) =>
    PROHIBITED_CONTROL_PLANE_FIELDS.has(field) || hasProhibitedField(nestedValue, inspected));
};

const hasUnexpectedFields = (value, allowedFields) =>
  !isPlainObject(value) || Object.keys(value).some((field) =>
    !allowedFields.has(field) && !PROHIBITED_CONTROL_PLANE_FIELDS.has(field));

const hasSchemaViolation = (descriptor) => {
  const safeDescriptor = isPlainObject(descriptor) ? descriptor : {};
  const grant = safeDescriptor.assetUsageGrant;
  const notices = isPlainObject(grant) ? grant.requiredNotices : undefined;

  return hasUnexpectedFields(safeDescriptor, DESCRIPTOR_FIELDS)
    || hasUnexpectedFields(safeDescriptor.resource, RESOURCE_FIELDS)
    || hasUnexpectedFields(safeDescriptor.provenance, PROVENANCE_FIELDS)
    || hasUnexpectedFields(grant, GRANT_FIELDS)
    || (Array.isArray(notices) && notices.some((notice) => hasUnexpectedFields(notice, NOTICE_FIELDS)));
};

const grantRequiresNotice = (grant) =>
  isPlainObject(grant)
  && REQUIRED_GRANT_POLICIES.some((policy) => grant[policy] === 'allowed-with-notice');

const hasValidGrantPolicies = (grant) =>
  isPlainObject(grant)
  && grant.evidenceKind === 'synthetic-test-fixture'
  && REQUIRED_GRANT_POLICIES.every((policy) => APPROVED_POLICY_VALUES.has(grant[policy]));

const hasValidNotices = (notices) =>
  Array.isArray(notices)
  && notices.every((notice) =>
    isPlainObject(notice)
    && isNonEmptyString(notice.text)
    && Array.isArray(notice.placements)
    && notice.placements.length > 0
    && notice.placements.every(isNonEmptyString));

const hasValidProvenance = (provenance) =>
  isPlainObject(provenance)
  && isNonEmptyString(provenance.evidenceId)
  && provenance.sourceKind === 'synthetic-fixture';

const result = (mode, reasonCodes) => ({
  mode,
  productionEligibility: 'BLOCKED_SYNTHETIC_FIXTURE',
  reasonCodes,
});

export const evaluateCatalogManifest = ({
  descriptor,
  pinnedResource,
  resourceByteLength,
  resourceDigest,
}) => {
  const reasonCodes = [];
  const safeDescriptor = isPlainObject(descriptor) ? descriptor : {};
  const resource = isPlainObject(safeDescriptor.resource) ? safeDescriptor.resource : {};
  const grant = isPlainObject(safeDescriptor.assetUsageGrant) ? safeDescriptor.assetUsageGrant : {};
  const notices = grant.requiredNotices;
  const provenance = isPlainObject(safeDescriptor.provenance) ? safeDescriptor.provenance : {};
  const hasMissingProvenance = !provenance.evidenceId || !provenance.sourceKind;
  const verifierMissing = resourceDigest === undefined || resourceByteLength === undefined;
  const verifierInvalid = !verifierMissing
    && (!isValidSha256(resourceDigest) || !isValidByteLength(resourceByteLength));

  addIfMissing(reasonCodes, !isNonEmptyString(safeDescriptor.assetId) || !isNonEmptyString(safeDescriptor.version), 'DESCRIPTOR_ID_OR_VERSION_MISSING');
  addIfMissing(reasonCodes, hasProhibitedField(descriptor), 'PROHIBITED_PROJECT_FIELD');
  addIfMissing(reasonCodes, hasSchemaViolation(descriptor), 'DESCRIPTOR_SCHEMA_INVALID');
  addIfMissing(reasonCodes, !isNonEmptyString(resource.mediaType), 'RESOURCE_DESCRIPTOR_INVALID');
  addIfMissing(reasonCodes, !isValidSha256(resource.sha256), 'RESOURCE_SHA256_INVALID');
  addIfMissing(reasonCodes, !isValidByteLength(resource.byteLength), 'RESOURCE_BYTE_LENGTH_INVALID');
  addIfMissing(reasonCodes, hasMissingProvenance, 'PROVENANCE_MISSING');
  addIfMissing(reasonCodes, !hasMissingProvenance && !hasValidProvenance(provenance), 'PROVENANCE_INVALID');
  addIfMissing(reasonCodes, !hasValidGrantPolicies(grant), 'GRANT_POLICY_INVALID');
  addIfMissing(reasonCodes, grantRequiresNotice(grant) && (!Array.isArray(notices) || notices.length === 0), 'GRANT_NOTICE_MISSING');
  addIfMissing(reasonCodes, notices !== undefined && !hasValidNotices(notices), 'GRANT_NOTICE_INVALID');
  addIfMissing(reasonCodes, Boolean(pinnedResource) && verifierMissing, 'RESOURCE_VERIFIER_MISSING');
  addIfMissing(reasonCodes, Boolean(pinnedResource) && verifierInvalid, 'RESOURCE_VERIFIER_INVALID');
  addIfMissing(reasonCodes, resourceDigest !== undefined && resourceDigest !== resource.sha256, 'RESOURCE_HASH_MISMATCH');
  addIfMissing(reasonCodes, resourceByteLength !== undefined && resourceByteLength !== resource.byteLength, 'RESOURCE_BYTES_MISMATCH');

  if (reasonCodes.length > 0) {
    return result('REJECTED', reasonCodes);
  }

  if (!pinnedResource) {
    return result('PREVIEW_ONLY', ['RESOURCE_NOT_PINNED']);
  }

  addIfMissing(reasonCodes, pinnedResource.sha256 !== resource.sha256, 'RESOURCE_HASH_MISMATCH');
  addIfMissing(reasonCodes, pinnedResource.byteLength !== resource.byteLength, 'RESOURCE_BYTES_MISMATCH');

  return reasonCodes.length > 0 ? result('REJECTED', reasonCodes) : result('EXPERIMENTAL_READY', []);
};

