import { createHash } from 'node:crypto';
import { describe, expect, it } from 'vitest';

import { evaluateCatalogCandidate } from '../../src/catalog-policy.mjs';
import { evaluateCatalogManifest } from '../../src/catalog-policy-core.mjs';

const sha256 = (value) => createHash('sha256').update(value).digest('hex');

const createGrant = (overrides = {}) => ({
  backupPackagingPolicy: 'allowed-with-notice',
  evidenceKind: 'synthetic-test-fixture',
  inAppRenderAndThumbnailPolicy: 'allowed-with-notice',
  modelAndSubresourcePolicy: 'allowed-with-notice',
  noticePlacementPolicy: 'allowed-with-notice',
  optimizationAndTranscodingPolicy: 'allowed-with-notice',
  private3dTransferPolicy: 'allowed-with-notice',
  renderedPngDownloadAndSharePolicy: 'allowed-with-notice',
  requiredNotices: [{
    placements: ['synthetic-ledger'],
    text: 'Synthetic fixture only — not for publication',
  }],
  ...overrides,
});

const createCandidate = (overrides = {}) => {
  const resourceBytes = overrides.resourceBytes ?? 'synthetic-chair-v1';
  const hash = overrides.hash ?? sha256(resourceBytes);
  const descriptor = {
    assetId: 'synthetic-chair',
    version: '1.0.0',
    resource: {
      byteLength: Buffer.byteLength(resourceBytes),
      mediaType: 'model/gltf-binary',
      sha256: hash,
    },
    provenance: {
      evidenceId: 'S6-SYNTH-001',
      sourceKind: 'synthetic-fixture',
    },
    assetUsageGrant: createGrant(),
  };

  return {
    descriptor: { ...descriptor, ...overrides.descriptor },
    pinnedResource: overrides.pinnedResource,
    resourceBytes,
  };
};

describe('synthetic catalog candidate policy', () => {
  it('allows a structurally valid unpinned synthetic resource only as a cancelable preview', () => {
    const result = evaluateCatalogCandidate(createCandidate());

    expect(result.mode).toBe('PREVIEW_ONLY');
    expect(result.reasonCodes).toEqual(['RESOURCE_NOT_PINNED']);
    expect(result.productionEligibility).toBe('BLOCKED_SYNTHETIC_FIXTURE');
  });

  it('permits the experiment to mark exact pinned bytes as ready without claiming production eligibility', () => {
    const resourceBytes = 'synthetic-chair-v1';
    const hash = sha256(resourceBytes);
    const result = evaluateCatalogCandidate(createCandidate({
      pinnedResource: { byteLength: Buffer.byteLength(resourceBytes), sha256: hash },
      resourceBytes,
    }));

    expect(result.mode).toBe('EXPERIMENTAL_READY');
    expect(result.reasonCodes).toEqual([]);
    expect(result.productionEligibility).toBe('BLOCKED_SYNTHETIC_FIXTURE');
  });

  it('rejects a mismatched pinned hash instead of marking a candidate durable', () => {
    const result = evaluateCatalogCandidate(createCandidate({
      pinnedResource: { byteLength: 18, sha256: '0'.repeat(64) },
    }));

    expect(result.mode).toBe('REJECTED');
    expect(result.reasonCodes).toContain('RESOURCE_HASH_MISMATCH');
  });

  it('rejects a grant that requires notice but omits the notice ledger', () => {
    const result = evaluateCatalogCandidate(createCandidate({
      descriptor: {
        assetUsageGrant: createGrant({ requiredNotices: [] }),
      },
    }));

    expect(result).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['GRANT_NOTICE_MISSING'],
    });
  });

  it('rejects a forbidden Project-data field at the catalog boundary', () => {
    const result = evaluateCatalogCandidate(createCandidate({
      descriptor: { projectId: 'must-not-cross-control-plane' },
    }));

    expect(result).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['PROHIBITED_PROJECT_FIELD'],
    });
  });

  it('rejects Project-shaped payloads nested inside otherwise permitted catalog metadata', () => {
    const candidates = [
      (() => {
        const candidate = createCandidate();
        candidate.descriptor.provenance.projectId = 'must-not-cross-control-plane';
        return candidate;
      })(),
      (() => {
        const candidate = createCandidate();
        candidate.descriptor.assetUsageGrant.projectData = { roomCount: 3 };
        return candidate;
      })(),
    ];

    for (const candidate of candidates) {
      expect(evaluateCatalogCandidate(candidate)).toMatchObject({
        mode: 'REJECTED',
        reasonCodes: ['PROHIBITED_PROJECT_FIELD'],
      });
    }
  });

  it('rejects unknown descriptor fields instead of accepting an unlisted payload shape', () => {
    const candidate = createCandidate();
    candidate.descriptor.provenance.projectOverview = { rooms: 3 };

    expect(evaluateCatalogCandidate(candidate)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['DESCRIPTOR_SCHEMA_INVALID'],
    });
  });

  it('rejects unknown fields at every descriptor boundary', () => {
    const candidates = [
      (() => {
        const candidate = createCandidate();
        candidate.descriptor.unexpected = true;
        return candidate;
      })(),
      (() => {
        const candidate = createCandidate();
        candidate.descriptor.resource.unexpected = true;
        return candidate;
      })(),
      (() => {
        const candidate = createCandidate();
        candidate.descriptor.assetUsageGrant.unexpected = true;
        return candidate;
      })(),
      (() => {
        const candidate = createCandidate();
        candidate.descriptor.assetUsageGrant.requiredNotices[0].unexpected = true;
        return candidate;
      })(),
    ];

    for (const candidate of candidates) {
      expect(evaluateCatalogCandidate(candidate)).toMatchObject({
        mode: 'REJECTED',
        reasonCodes: ['DESCRIPTOR_SCHEMA_INVALID'],
      });
    }
  });

  it('rejects a cyclic unlisted payload without recursing past the catalog boundary', () => {
    const candidate = createCandidate();
    candidate.descriptor.provenance.cycle = candidate.descriptor;

    expect(evaluateCatalogCandidate(candidate)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['DESCRIPTOR_SCHEMA_INVALID'],
    });
  });

  it('keeps a structurally valid browser-side descriptor preview-only when a byte verifier is unavailable', () => {
    const candidate = createCandidate();
    const result = evaluateCatalogManifest({ descriptor: candidate.descriptor });

    expect(result.mode).toBe('PREVIEW_ONLY');
    expect(result.reasonCodes).toEqual(['RESOURCE_NOT_PINNED']);
  });

  it('rejects an absent descriptor before it can become a catalog candidate', () => {
    const result = evaluateCatalogManifest({});

    expect(result.mode).toBe('REJECTED');
    expect(result.reasonCodes).toContain('DESCRIPTOR_ID_OR_VERSION_MISSING');
    expect(result.reasonCodes).toContain('RESOURCE_DESCRIPTOR_INVALID');
  });

  it('rejects each independently missing descriptor identity field', () => {
    for (const field of ['assetId', 'version']) {
      const candidate = createCandidate();
      candidate.descriptor[field] = '';

      const result = evaluateCatalogManifest({ descriptor: candidate.descriptor });
      expect(result).toMatchObject({
        mode: 'REJECTED',
        reasonCodes: ['DESCRIPTOR_ID_OR_VERSION_MISSING'],
      });
    }
  });

  it('rejects a descriptor with a separately missing resource field', () => {
    const expectedReasonByField = {
      byteLength: 'RESOURCE_BYTE_LENGTH_INVALID',
      mediaType: 'RESOURCE_DESCRIPTOR_INVALID',
      sha256: 'RESOURCE_SHA256_INVALID',
    };

    for (const field of Object.keys(expectedReasonByField)) {
      const candidate = createCandidate();
      candidate.descriptor.resource[field] = field === 'byteLength' ? null : '';

      const result = evaluateCatalogManifest({ descriptor: candidate.descriptor });
      expect(result).toMatchObject({
        mode: 'REJECTED',
        reasonCodes: [expectedReasonByField[field]],
      });
    }
  });

  it('rejects malformed resource descriptors even when a matching pin attempts to mask them', () => {
    const validHash = sha256('synthetic-chair-v1');
    const malformedHash = evaluateCatalogManifest({
      descriptor: createCandidate({
        descriptor: {
          resource: {
            byteLength: 18,
            mediaType: 'model/gltf-binary',
            sha256: 'g'.repeat(64),
          },
        },
      }).descriptor,
      pinnedResource: { byteLength: 18, sha256: 'g'.repeat(64) },
    });
    const negativeByteLength = evaluateCatalogManifest({
      descriptor: createCandidate({
        descriptor: {
          resource: {
            byteLength: -1,
            mediaType: 'model/gltf-binary',
            sha256: validHash,
          },
        },
      }).descriptor,
      pinnedResource: { byteLength: -1, sha256: validHash },
    });

    expect(malformedHash).toEqual({
      mode: 'REJECTED',
      productionEligibility: 'BLOCKED_SYNTHETIC_FIXTURE',
      reasonCodes: ['RESOURCE_SHA256_INVALID', 'RESOURCE_VERIFIER_MISSING'],
    });
    expect(negativeByteLength).toEqual({
      mode: 'REJECTED',
      productionEligibility: 'BLOCKED_SYNTHETIC_FIXTURE',
      reasonCodes: ['RESOURCE_BYTE_LENGTH_INVALID', 'RESOURCE_VERIFIER_MISSING'],
    });
  });

  it('rejects coercible, unanchored, or zero-length resource descriptors', () => {
    const validHash = sha256('synthetic-chair-v1');
    const malformedHashes = [
      [validHash],
      `z${validHash}`,
      `${validHash}z`,
    ];

    for (const hash of malformedHashes) {
      const candidate = createCandidate();
      candidate.descriptor.resource.sha256 = hash;

      expect(evaluateCatalogManifest({ descriptor: candidate.descriptor })).toMatchObject({
        mode: 'REJECTED',
        reasonCodes: ['RESOURCE_SHA256_INVALID'],
      });
    }

    const zeroLength = evaluateCatalogManifest({
      descriptor: createCandidate({
        descriptor: {
          resource: {
            byteLength: 0,
            mediaType: 'model/gltf-binary',
            sha256: validHash,
          },
        },
      }).descriptor,
      pinnedResource: { byteLength: 0, sha256: validHash },
      resourceByteLength: 0,
      resourceDigest: validHash,
    });

    expect(zeroLength).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['RESOURCE_BYTE_LENGTH_INVALID', 'RESOURCE_VERIFIER_INVALID'],
    });
  });

  it('requires a byte verifier before a pinned resource can become experiment-ready', () => {
    const candidate = createCandidate({
      pinnedResource: {
        byteLength: 18,
        sha256: sha256('synthetic-chair-v1'),
      },
    });

    expect(evaluateCatalogManifest({
      descriptor: candidate.descriptor,
      pinnedResource: candidate.pinnedResource,
    })).toEqual({
      mode: 'REJECTED',
      productionEligibility: 'BLOCKED_SYNTHETIC_FIXTURE',
      reasonCodes: ['RESOURCE_VERIFIER_MISSING'],
    });

    for (const partialVerifier of [
      { resourceByteLength: 18 },
      { resourceDigest: sha256('synthetic-chair-v1') },
    ]) {
      expect(evaluateCatalogManifest({
        descriptor: candidate.descriptor,
        pinnedResource: candidate.pinnedResource,
        ...partialVerifier,
      })).toMatchObject({
        mode: 'REJECTED',
        reasonCodes: ['RESOURCE_VERIFIER_MISSING'],
      });
    }
  });

  it('reports a malformed verifier even when another mismatch already rejects the pin', () => {
    const resourceBytes = 'synthetic-chair-v1';
    const candidate = createCandidate({
      pinnedResource: { byteLength: 18, sha256: sha256(resourceBytes) },
      resourceBytes,
    });

    expect(evaluateCatalogManifest({
      descriptor: candidate.descriptor,
      pinnedResource: candidate.pinnedResource,
      resourceByteLength: 18,
      resourceDigest: 'g'.repeat(64),
    })).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['RESOURCE_VERIFIER_INVALID', 'RESOURCE_HASH_MISMATCH'],
    });
  });

  it('verifies byte arrays as well as string fixtures before pinning', () => {
    const resourceBytes = Buffer.from('synthetic-chair-v1');
    const result = evaluateCatalogCandidate(createCandidate({
      pinnedResource: { byteLength: resourceBytes.byteLength, sha256: sha256(resourceBytes) },
      resourceBytes,
    }));

    expect(result).toEqual({
      mode: 'EXPERIMENTAL_READY',
      productionEligibility: 'BLOCKED_SYNTHETIC_FIXTURE',
      reasonCodes: [],
    });
  });

  it('rejects missing provenance before a resource can be pinned', () => {
    for (const field of ['evidenceId', 'sourceKind']) {
      const candidate = createCandidate();
      candidate.descriptor.provenance[field] = '';

      const result = evaluateCatalogCandidate(candidate);
      expect(result).toMatchObject({
        mode: 'REJECTED',
        reasonCodes: ['PROVENANCE_MISSING'],
      });
    }
  });

  it('requires every grant policy rather than accepting one safe policy', () => {
    const candidate = createCandidate();
    candidate.descriptor.assetUsageGrant.private3dTransferPolicy = 'forbidden';

    const result = evaluateCatalogCandidate(candidate);

    expect(result).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['GRANT_POLICY_INVALID'],
    });
  });

  it('requires the synthetic fixture evidence kind rather than policy strings alone', () => {
    const candidate = createCandidate();
    candidate.descriptor.assetUsageGrant.evidenceKind = 'human-grant-claim';

    expect(evaluateCatalogCandidate(candidate)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['GRANT_POLICY_INVALID'],
    });
  });

  it('rejects a source hash or byte-length mismatch before the pin check', () => {
    const hashMismatch = createCandidate({ hash: 'f'.repeat(64) });
    const bytesMismatch = createCandidate({
      descriptor: {
        resource: {
          byteLength: 17,
          mediaType: 'model/gltf-binary',
          sha256: sha256('synthetic-chair-v1'),
        },
      },
    });

    expect(evaluateCatalogCandidate(hashMismatch)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['RESOURCE_HASH_MISMATCH'],
    });
    expect(evaluateCatalogCandidate(bytesMismatch)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['RESOURCE_BYTES_MISMATCH'],
    });
  });

  it('rejects every forbidden Project-shaped field rather than only projectId', () => {
    for (const field of ['project', 'projectData', 'revision', 'revisionId', 'history', 'portableBackup']) {
      const candidate = createCandidate();
      candidate.descriptor[field] = 'forbidden-control-plane-data';

      const result = evaluateCatalogCandidate(candidate);
      expect(result).toMatchObject({
        mode: 'REJECTED',
        reasonCodes: ['PROHIBITED_PROJECT_FIELD'],
      });
    }
  });

  it('accepts the fully allowed synthetic policy in the experiment without treating it as production-ready', () => {
    const resourceBytes = 'synthetic-chair-v1';
    const candidate = createCandidate({
      pinnedResource: { byteLength: Buffer.byteLength(resourceBytes), sha256: sha256(resourceBytes) },
      resourceBytes,
    });
    candidate.descriptor.assetUsageGrant = createGrant({
      backupPackagingPolicy: 'allowed',
      inAppRenderAndThumbnailPolicy: 'allowed',
      modelAndSubresourcePolicy: 'allowed',
      noticePlacementPolicy: 'allowed',
      optimizationAndTranscodingPolicy: 'allowed',
      private3dTransferPolicy: 'allowed',
      renderedPngDownloadAndSharePolicy: 'allowed',
      requiredNotices: [],
    });

    expect(evaluateCatalogCandidate(candidate)).toEqual({
      mode: 'EXPERIMENTAL_READY',
      productionEligibility: 'BLOCKED_SYNTHETIC_FIXTURE',
      reasonCodes: [],
    });
  });

  it('requires a notice when any one grant policy is allowed-with-notice', () => {
    const candidate = createCandidate();
    candidate.descriptor.assetUsageGrant = createGrant({
      backupPackagingPolicy: 'allowed',
      inAppRenderAndThumbnailPolicy: 'allowed',
      modelAndSubresourcePolicy: 'allowed',
      noticePlacementPolicy: 'allowed',
      optimizationAndTranscodingPolicy: 'allowed',
      private3dTransferPolicy: 'allowed',
      renderedPngDownloadAndSharePolicy: 'allowed-with-notice',
      requiredNotices: [],
    });

    expect(evaluateCatalogCandidate(candidate)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['GRANT_NOTICE_MISSING'],
    });
  });

  it('rejects a notice-required grant when its notice ledger is absent rather than merely empty', () => {
    const candidate = createCandidate();
    delete candidate.descriptor.assetUsageGrant.requiredNotices;

    expect(evaluateCatalogCandidate(candidate)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['GRANT_NOTICE_MISSING'],
    });
  });

  it('rejects an empty notice, a notice without placement, and malformed synthetic provenance', () => {
    const emptyNotice = createCandidate();
    emptyNotice.descriptor.assetUsageGrant.requiredNotices = [{
      placements: ['synthetic-ledger'],
      text: '',
    }];
    const missingPlacement = createCandidate();
    missingPlacement.descriptor.assetUsageGrant.requiredNotices = [{
      placements: [],
      text: 'Synthetic fixture only — not for publication',
    }];
    const malformedProvenance = createCandidate();
    malformedProvenance.descriptor.provenance.sourceKind = {};
    const whitespaceEvidenceId = createCandidate();
    whitespaceEvidenceId.descriptor.provenance.evidenceId = ' ';
    const incompletePlacements = createCandidate();
    incompletePlacements.descriptor.assetUsageGrant.requiredNotices = [{
      placements: ['synthetic-ledger', ''],
      text: 'Synthetic fixture only — not for publication',
    }];

    expect(evaluateCatalogCandidate(emptyNotice)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['GRANT_NOTICE_INVALID'],
    });
    expect(evaluateCatalogCandidate(missingPlacement)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['GRANT_NOTICE_INVALID'],
    });
    expect(evaluateCatalogCandidate(malformedProvenance)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['PROVENANCE_INVALID'],
    });
    expect(evaluateCatalogCandidate(whitespaceEvidenceId)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['PROVENANCE_INVALID'],
    });
    expect(evaluateCatalogCandidate(incompletePlacements)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['GRANT_NOTICE_INVALID'],
    });
  });

  it('rejects a pinned resource when its byte length does not equal the descriptor', () => {
    const resourceBytes = 'synthetic-chair-v1';
    const candidate = createCandidate({
      pinnedResource: { byteLength: 17, sha256: sha256(resourceBytes) },
      resourceBytes,
    });

    expect(evaluateCatalogCandidate(candidate)).toMatchObject({
      mode: 'REJECTED',
      reasonCodes: ['RESOURCE_BYTES_MISMATCH'],
    });
  });
});
